// On a cold start /crises is empty because nothing has been scored yet, so
// fall back to a bootstrap list matching the DB seed. Used ONLY when the API
// returns an empty cohort.
const BOOTSTRAP = ['AFG','BFA','CAF','CMR','COD','COL','ETH','HTI','IRQ','LBN','LBY','MLI','MMR','MOZ','NER','NGA','PSE','SDN','SOM','SSD','SYR','TCD','UKR','VEN','YEM','ZWE'];

const response = $input.first().json;
const fromApi = (response.data ?? []).map((c) => c.iso3).filter(Boolean);
const iso3s = fromApi.length > 0 ? fromApi : BOOTSTRAP;

// GDELT has no bulk endpoint — one query per country. One item per country
// lets the HTTP node fan out and n8n handle pacing.
return iso3s.map((iso3) => ({ json: { iso3 } }));

// GDELT returns HTML or an empty body when throttled, so nothing is trusted.
const observedAt = new Date().toISOString().slice(0, 10);
const observations = [];
const skipped = [];

for (const item of $input.all()) {
  const iso3 = item.json.iso3;
  if (!iso3) continue;

  // timelinevol shape: { timeline: [ { data: [ { date, value }, ... ] } ] }
  const series = item.json?.timeline?.[0]?.data;
  if (!Array.isArray(series) || series.length === 0) {
    skipped.push(iso3);
    continue;
  }

  const value = Number(series[series.length - 1]?.value);
  if (!Number.isFinite(value) || value < 0) {
    skipped.push(iso3);
    continue;
  }

  observations.push({ iso3, source: 'gdelt', metric: 'coverage_volume_pct', value, observedAt });
}

if (skipped.length > 0) console.warn('GDELT: no usable series for ' + skipped.join(', '));

// A run that produced nothing must fail loudly rather than POST an empty batch
// and be recorded as a success.
if (observations.length === 0) {
  throw new Error('GDELT returned no usable data for any country — likely throttled.');
}

return [{ json: { source: 'gdelt', observations, triggerScoring: false } }];
